#include "apex/desktop_overlay.hpp"
#include <windows.h>
#include <iostream>
#include <stdexcept>
void require(bool v,const char* s){if(!v)throw std::runtime_error(s);}
COLORREF pixel(HWND window,int x,int y){RECT r{};GetClientRect(window,&r);HDC screen=GetDC(nullptr),dc=CreateCompatibleDC(screen);HBITMAP bitmap=CreateCompatibleBitmap(screen,r.right,r.bottom);auto old=SelectObject(dc,bitmap);SendMessageW(window,WM_PRINTCLIENT,reinterpret_cast<WPARAM>(dc),PRF_CLIENT);auto p=GetPixel(dc,x,y);SelectObject(dc,old);DeleteObject(bitmap);DeleteDC(dc);ReleaseDC(nullptr,screen);return p;}
int main(){try{apex::DesktopOverlayOptions o;o.enabled=true;apex::EnemySnapshot s;s.completed=1;s.status="ready";s.observedAt=std::chrono::steady_clock::now();s.analyzedFrame=std::make_shared<apex::CapturedFrame>();s.latest.boxes.push_back({.25f,.25f,.75f,.75f,.9f});auto before=GetGuiResources(GetCurrentProcess(),GR_GDIOBJECTS);{
 apex::DesktopOverlay overlay;require(!overlay.monitors().empty(),"No monitor enumerated");auto focus=GetForegroundWindow();overlay.update(o,s,true,1920,1080);HWND window=FindWindowW(L"ApexVisualizationDesktopOverlay",nullptr);require(window&&IsWindowVisible(window),"Actual overlay window not visible");auto style=GetWindowLongPtrW(window,GWL_EXSTYLE);auto flags=WS_EX_LAYERED|WS_EX_TRANSPARENT|WS_EX_TOPMOST|WS_EX_NOACTIVATE|WS_EX_TOOLWINDOW;require((style&flags)==flags,"Overlay style flags wrong");require(GetForegroundWindow()==focus,"Overlay stole keyboard focus");require(SendMessageW(window,WM_NCHITTEST,0,0)==HTTRANSPARENT,"Overlay intercepted clicks");COLORREF key=1;BYTE alpha=0;DWORD modes=0;require(GetLayeredWindowAttributes(window,&key,&alpha,&modes)&&key==RGB(0,0,0)&&(modes&LWA_COLORKEY),"Transparency not configured");RECT r;GetClientRect(window,&r);auto v=apex::overlayViewport(float(r.right),float(r.bottom),1920,1080,true);int x=int(v.x+.25f*v.width),y=int(v.y+.5f*v.height);require(pixel(window,x,y)==RGB(210,110,255),"Actual GDI candidate edge not painted");for(int i=0;i<200;++i){s.completed++;s.observedAt=std::chrono::steady_clock::now();overlay.update(o,s,true,1920,1080);}s.observedAt=std::chrono::steady_clock::now()-std::chrono::seconds(2);overlay.update(o,s,true,1920,1080);require(pixel(window,x,y)==RGB(0,0,0),"Stale boxes retained");overlay.update(o,s,false,1920,1080);require(!IsWindowVisible(window),"Overlay stayed visible after live source stopped");o.enabled=false;overlay.update(o,s,true,1920,1080);require(!IsWindowVisible(window),"Overlay off failed");}
 require(!FindWindowW(L"ApexVisualizationDesktopOverlay",nullptr),"Overlay window leaked");auto after=GetGuiResources(GetCurrentProcess(),GR_GDIOBJECTS);require(after<=before+4,"GDI objects grew over repeated repaint and cleanup");std::cout<<"PASS actual layered window, transparency, click-through/focus, monitor positioning, GDI box pixels, stale clearing, source stop, 200 repaints and resource cleanup; not an Apex compatibility test\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
